fn numpy_greater_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // Ensure both inputs have the same length
    assert_eq!(x1.len(), x2.len(), "Input vectors must have the same length");
    
    // Zip the two vectors together, compare element-wise, and collect the results
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| a >= b)
      .collect()
}

